namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    public int Id { get; set; }

    [Required(ErrorMessage = "Student name is required.")]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    public string StudentId { get; set; } = string.Empty;

    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }

    public DateTime SubmittedAt { get; set; }

    public string CourseName { get; set; } = string.Empty;
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollmentRequests = new();
    private int _nextEnrollmentId = 1;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language arts." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Title = "Introduction to Programming", Code = "CS 101", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, functions, and object-oriented programming.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a PhD from MIT.", DepartmentId = 1, IsFeatured = true },
            new() { Id = 2, Title = "Data Structures and Algorithms", Code = "CS 201", Description = "Study of fundamental data structures including arrays, linked lists, trees, and graphs. Algorithm design and analysis.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. James Wright", InstructorBio = "Dr. Wright specializes in algorithm optimization and has published over 30 papers in top-tier journals.", DepartmentId = 1, IsFeatured = true },
            new() { Id = 3, Title = "Calculus I", Code = "MATH 151", Description = "Introduction to differential calculus including limits, derivatives, and applications.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Maria Rodriguez", InstructorBio = "Dr. Rodriguez is an award-winning educator with expertise in applied mathematics.", DepartmentId = 2, IsFeatured = false },
            new() { Id = 4, Title = "Linear Algebra", Code = "MATH 220", Description = "Study of vector spaces, matrices, linear transformations, and eigenvalues.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Alan Park", InstructorBio = "Dr. Park's research focuses on computational linear algebra and numerical methods.", DepartmentId = 2, IsFeatured = true },
            new() { Id = 5, Title = "General Physics I", Code = "PHYS 101", Description = "Mechanics, thermodynamics, and waves. Includes laboratory component.", Credits = 4, Schedule = "Mon/Wed 2:00–3:15 PM, Lab: Fri 2:00–4:50 PM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is a former NASA researcher specializing in astrophysics and mechanics.", DepartmentId = 3, IsFeatured = true },
            new() { Id = 6, Title = "Quantum Mechanics", Code = "PHYS 301", Description = "Introduction to quantum theory, wave functions, and the Schrödinger equation.", Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", InstructorName = "Dr. Elena Vasquez", InstructorBio = "Dr. Vasquez conducts research in quantum computing and has received multiple NSF grants.", DepartmentId = 3, IsFeatured = false },
            new() { Id = 7, Title = "English Composition", Code = "ENG 101", Description = "Develop critical writing skills through essays, research papers, and peer review.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Prof. David Thompson", InstructorBio = "Prof. Thompson is a published author and has taught composition for over 20 years.", DepartmentId = 4, IsFeatured = false },
            new() { Id = 8, Title = "American Literature", Code = "ENG 250", Description = "Survey of American literature from colonial period to contemporary works.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. Lisa Monroe", InstructorBio = "Dr. Monroe specializes in 20th-century American fiction and has authored three books on the subject.", DepartmentId = 4, IsFeatured = true }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses() => _courses;

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.ToLower();
            query = query.Where(c =>
                c.Title.ToLower().Contains(term) ||
                c.Code.ToLower().Contains(term) ||
                c.Description.ToLower().Contains(term) ||
                c.InstructorName.ToLower().Contains(term));
        }

        return query.ToList();
    }

    public void SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        request.Id = _nextEnrollmentId++;
        request.SubmittedAt = DateTime.Now;
        var course = GetCourse(request.CourseId);
        request.CourseName = course?.Title ?? "Unknown";
        _enrollmentRequests.Add(request);
    }

    public List<EnrollmentRequest> GetEnrollmentRequests() => _enrollmentRequests;
}

