@page "/courses"
@rendermode InteractiveServer
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<PageTitle>Courses</PageTitle>

<h1>Course Catalog</h1>

<div class="filter-bar">
    <input type="text" class="form-control search-input" placeholder="Search courses..."
           @bind="searchTerm" @bind:event="oninput" />
    <select class="form-control dept-filter" @bind="selectedDepartmentId">
        <option value="0">All Departments</option>
        @foreach (var dept in CatalogService.GetDepartments())
        {
            <option value="@dept.Id">@dept.Name</option>
        }
    </select>
</div>

<table class="table course-table">
    <thead>
        <tr>
            <th>Code</th>
            <th>Title</th>
            <th>Credits</th>
            <th>Schedule</th>
            <th>Instructor</th>
        </tr>
    </thead>
    <tbody>
        @foreach (var course in FilteredCourses)
        {
            <tr>
                <td>@course.Code</td>
                <td><a href="/courses/@course.Id">@course.Title</a></td>
                <td>@course.Credits</td>
                <td>@course.Schedule</td>
                <td>@course.InstructorName</td>
            </tr>
        }
    </tbody>
</table>

@if (!FilteredCourses.Any())
{
    <p class="no-results">No courses found matching your criteria.</p>
}

@code {
    private string? searchTerm;
    private int selectedDepartmentId;

    private List<UniversityCourseCatalog.Models.Course> FilteredCourses =>
        CatalogService.SearchCourses(searchTerm, selectedDepartmentId > 0 ? selectedDepartmentId : null);
}

@page "/courses/{Id:int}"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<PageTitle>@(course?.Title ?? "Course Detail")</PageTitle>

@if (course is null)
{
    <p>Course not found.</p>
}
else
{
    <div class="course-detail">
        <h1>@course.Title</h1>
        <p class="course-code-detail">@course.Code</p>

        <div class="detail-grid">
            <div class="detail-item">
                <strong>Credits:</strong> @course.Credits
            </div>
            <div class="detail-item">
                <strong>Schedule:</strong> @course.Schedule
            </div>
            <div class="detail-item">
                <strong>Department:</strong> @(CatalogService.GetDepartment(course.DepartmentId)?.Name)
            </div>
        </div>

        <h2>Description</h2>
        <p>@course.Description</p>

        <h2>Instructor</h2>
        <p><strong>@course.InstructorName</strong></p>
        <p>@course.InstructorBio</p>

        <div class="detail-actions">
            <a href="/courses" class="btn btn-secondary">← Back to Courses</a>
            <a href="/enroll" class="btn btn-primary">Enroll in this Course</a>
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private UniversityCourseCatalog.Models.Course? course;

    protected override void OnInitialized()
    {
        course = CatalogService.GetCourse(Id);
    }
}

@page "/enroll"
@rendermode InteractiveServer
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>

@if (submitted)
{
    <div class="confirmation-message">
        <h2>✓ Enrollment Request Submitted</h2>
        <p>Thank you, <strong>@model.StudentName</strong>! Your enrollment request for <strong>@model.CourseName</strong> has been received.</p>
        <p>Student ID: @model.StudentId</p>
        <a href="/courses" class="btn btn-primary">Browse More Courses</a>
    </div>
}
else
{
    <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="enrollment">
        <DataAnnotationsValidator />
        <ValidationSummary />

        <div class="form-group mb-3">
            <label for="studentName">Student Name</label>
            <InputText id="studentName" class="form-control" @bind-Value="model.StudentName" />
            <ValidationMessage For="() => model.StudentName" />
        </div>

        <div class="form-group mb-3">
            <label for="studentId">Student ID</label>
            <InputText id="studentId" class="form-control" @bind-Value="model.StudentId" />
            <ValidationMessage For="() => model.StudentId" />
        </div>

        <div class="form-group mb-3">
            <label for="courseId">Course</label>
            <InputSelect id="courseId" class="form-control" @bind-Value="model.CourseId">
                <option value="0">-- Select a course --</option>
                @foreach (var course in CatalogService.GetCourses())
                {
                    <option value="@course.Id">@course.Code - @course.Title</option>
                }
            </InputSelect>
            <ValidationMessage For="() => model.CourseId" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
    </EditForm>
}

@code {
    private UniversityCourseCatalog.Models.EnrollmentRequest model = new();
    private bool submitted;

    private void HandleSubmit()
    {
        CatalogService.SubmitEnrollmentRequest(model);
        submitted = true;
    }
}

