<PageTitle>Departments</PageTitle>

<h1>Departments</h1>

<div class="dept-grid">
    @foreach (var dept in CatalogService.GetDepartments())
    {
        <div class="dept-card">
            <h2>@dept.Name</h2>
            <p class="dept-code">@dept.Code</p>
            <p>@dept.Description</p>
            <a href="/courses?departmentId=@dept.Id" class="btn btn-secondary">View Courses →</a>
        </div>
    }
</div>

