 @page "/enroll"
 @rendermode InteractiveServer
 @inject UniversityCourseCatalog.Services.CatalogService CatalogService

 <PageTitle>Enrollment Request</PageTitle>

 <h1>Enrollment Request</h1>

 @if (submitted)
 {
     <div class="confirmation-message">
         <h2>✓ Enrollment Request Submitted</h2>
         <p>Thank you, <strong>@model.StudentName</strong>! Your enrollment request for <strong>@model.CourseName</strong> has been received.</p>
         <p>Student ID: @model.StudentId</p>
         <a href="/courses" class="btn btn-primary">Browse More Courses</a>
     </div>
 }
 else
 {
     <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="enrollment">
         <DataAnnotationsValidator />
         <ValidationSummary />

         <div class="form-group mb-3">
             <label for="studentName">Student Name</label>
             <InputText id="studentName" class="form-control" @bind-Value="model.StudentName" />
             <ValidationMessage For="() => model.StudentName" />
         </div>

         <div class="form-group mb-3">
             <label for="studentId">Student ID</label>
             <InputText id="studentId" class="form-control" @bind-Value="model.StudentId" />
             <ValidationMessage For="() => model.StudentId" />
         </div>

         <div class="form-group mb-3">
             <label for="courseId">Course</label>
             <InputSelect id="courseId" class="form-control" @bind-Value="model.CourseId">
                 <option value="0">-- Select a course --</option>
                 @foreach (var course in CatalogService.GetCourses())
                 {
                     <option value="@course.Id">@course.Code - @course.Title</option>
                 }
             </InputSelect>
             <ValidationMessage For="() => model.CourseId" />
         </div>

         <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
     </EditForm>
 }

 @code {
     private UniversityCourseCatalog.Models.EnrollmentRequest model = new();
     private bool submitted;

     private void HandleSubmit()
     {
         CatalogService.SubmitEnrollmentRequest(model);
         submitted = true;
     }
 }

